CREATE TABLE public.tender_quantities (tender_id uuid PRIMARY KEY REFERENCES public.tenders(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES public.companies(id), analysis_run uuid NOT NULL, status text NOT NULL CHECK(status IN ('analyzing','analysed','error')), result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tender_quantities TO authenticated;
GRANT ALL ON public.tender_quantities TO service_role;
ALTER TABLE public.tender_quantities ENABLE ROW LEVEL SECURITY;
CREATE POLICY tender_quantities_company ON public.tender_quantities FOR ALL TO authenticated USING(company_id=public.my_company()) WITH CHECK(company_id=public.my_company() AND EXISTS(SELECT 1 FROM public.tenders t WHERE t.id=tender_id AND t.company_id=public.my_company()));
CREATE TRIGGER tender_quantities_validate BEFORE INSERT OR UPDATE ON public.tender_quantities FOR EACH ROW EXECUTE FUNCTION public.estim_validate_tender_insights();
CREATE FUNCTION public.estim_clear_tender_quantities() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='tenders' THEN IF NEW.analysis_run IS DISTINCT FROM OLD.analysis_run THEN DELETE FROM public.tender_quantities WHERE tender_id=NEW.id; END IF; RETURN NEW; ELSE DELETE FROM public.tender_quantities WHERE tender_id=OLD.tender_id; RETURN OLD; END IF; END $$;
CREATE TRIGGER tender_quantities_reset AFTER UPDATE ON public.tenders FOR EACH ROW EXECUTE FUNCTION public.estim_clear_tender_quantities();
CREATE TRIGGER tender_quantities_file_removed AFTER DELETE ON public.tender_documents FOR EACH ROW EXECUTE FUNCTION public.estim_clear_tender_quantities();
CREATE FUNCTION public.estim_claim_tender_quantities(tid uuid,rid uuid) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE cid uuid; BEGIN SELECT company_id INTO cid FROM public.tenders WHERE id=tid AND company_id=public.my_company() AND analysis_run=rid AND status='analysed' FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.tender_insights WHERE tender_id=tid AND analysis_run=rid AND status='analysed') OR EXISTS(SELECT 1 FROM public.tender_documents WHERE tender_id=tid AND analysis_status NOT IN ('analysed','too_large')) THEN RETURN false; END IF; INSERT INTO public.tender_quantities(tender_id,company_id,analysis_run,status) VALUES(tid,cid,rid,'analyzing') ON CONFLICT(tender_id) DO NOTHING; IF NOT FOUND THEN RETURN false; END IF; UPDATE public.tenders SET status='analyzing',analysis_started_at=now() WHERE id=tid; RETURN true; END $$;
CREATE FUNCTION public.estim_finish_tender_quantities(tid uuid,rid uuid,p_result jsonb,p_error text) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN p_error:=nullif(p_error,''); PERFORM 1 FROM public.tenders WHERE id=tid AND company_id=public.my_company() AND analysis_run=rid AND status='analyzing' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Analysen har ersatts.'; END IF; IF p_result IS NOT NULL AND (jsonb_typeof(p_result)<>'object' OR NOT(p_result ?& ARRAY['rules','items','assumptions'])) THEN RAISE EXCEPTION 'Invalid quantity result'; END IF; UPDATE public.tender_quantities SET result=p_result,error=left(p_error,500),status=CASE WHEN p_error IS NULL THEN 'analysed' ELSE 'error' END WHERE tender_id=tid AND analysis_run=rid AND status='analyzing'; IF NOT FOUND THEN RAISE EXCEPTION 'Underlaget har ändrats. Analysera igen.'; END IF; UPDATE public.tenders SET status=CASE WHEN p_error IS NULL THEN 'analysed' ELSE 'error' END,error=left(p_error,500) WHERE id=tid; END $$;
CREATE INDEX tender_quantities_company_idx ON public.tender_quantities(company_id);
REVOKE ALL ON FUNCTION public.estim_clear_tender_quantities(),public.estim_claim_tender_quantities(uuid,uuid),public.estim_finish_tender_quantities(uuid,uuid,jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.estim_claim_tender_quantities(uuid,uuid),public.estim_finish_tender_quantities(uuid,uuid,jsonb,text) TO authenticated;